const POSTHOG_ENABLED = Boolean(
  process.env.NEXT_PUBLIC_POSTHOG_KEY && process.env.NEXT_PUBLIC_POSTHOG_HOST,
);

export const ANALYTICS_EVENTS = [
  'restaurant_list_viewed',
  'restaurant_selected',
  'restaurants_empty',
  'restaurants_list_error',
  'select_date',
  'select_party',
