  'auth_signin_error',
  'auth_signin_success',
  'auth_magiclink_sent',
  'user_signed_up',
] as const;

export type AnalyticsEvent = (typeof ANALYTICS_EVENTS)[number];

type PosthogQueuedEvent = { event: string; payload: AnalyticsProps };

type PlausibleEventOptions = {
  props?: AnalyticsProps;
  url?: string;
  referrer?: string;
  revenue?: number;
  callback?: () => void;
};

type PlausibleWindow = Window & {
  plausible?: (event: AnalyticsEvent, options?: PlausibleEventOptions) => void;
};

type PosthogWindow = Window & {
  posthog?: {
    capture: (event: string, payload?: AnalyticsProps) => void;
  };
  __posthogQueue?: PosthogQueuedEvent[];
};

function capturePosthog(event: AnalyticsEvent, payload: AnalyticsProps): void {
  if (typeof window === 'undefined' || !POSTHOG_ENABLED) return;

  const win = window as PosthogWindow;
  if (win.posthog && typeof win.posthog.capture === 'function') {
    win.posthog.capture(event, payload);
    return;
  }

  if (!win.__posthogQueue) {
    win.__posthogQueue = [];
  }
  win.__posthogQueue.push({ event, payload });
}

export function track(event: AnalyticsEvent, props?: Record<string, unknown>) {
  if (typeof window === 'undefined') return;
  if (!ANALYTICS_EVENTS.includes(event)) {
    if (DEBUG_ENABLED) {
      console.warn('[analytics] refused to send unknown event', event);
    }
    return;
  }

  const payload = sanitizeAnalyticsProps(props);
  const plausible = (window as PlausibleWindow).plausible;

  try {
    if (typeof plausible === 'function') {
      plausible(event, payload ? { props: payload } : undefined);
    }
  } catch (error) {
    if (DEBUG_ENABLED) {
      console.warn('[analytics] failed to send event', event, error);
    }
  }

  try {
    capturePosthog(event, payload ?? {});
  } catch (error) {
    if (DEBUG_ENABLED) {
      console.warn('[analytics] failed to send event to PostHog', event, error);
    }
  }

  if (DEBUG_ENABLED) {
    console.debug(`[analytics] ${event}`, payload ?? {});
  }
}

'use client';

import { sanitizeAnalyticsProps, type AnalyticsJsonValue } from '@/lib/analytics/schema';
import { stripUrlQueryAndHash } from '@/lib/security/url-redaction';
import { getSupabaseBrowserClient } from '@/lib/supabase/browser';
import {
  getSupabaseSessionSnapshot,
  subscribeToSupabaseSession,
} from '@/lib/supabase/session-store';

const EVENT_ENDPOINT = '/api/v1/events';
const STORAGE_KEY = 'srx.analytics.anonId';
const FLUSH_INTERVAL_MS = 5_000;
const MAX_BATCH_SIZE = 10;
const DEBUG_ENABLED = process.env.NODE_ENV !== 'production';
const APP_VERSION =
  process.env.NEXT_PUBLIC_APP_VERSION ?? process.env.NEXT_PUBLIC_VERCEL_GIT_COMMIT_SHA ?? 'web-dev';

export type AnalyticsEventProps = Record<string, AnalyticsJsonValue>;

export type AnalyticsUser = {
  anonId: string;
  emailHash: string | null;
};

export type AnalyticsContext = {
  route: string;
  version: string;
};

export type AnalyticsEventPayload = {
  name: string;
  ts: string;
  user: AnalyticsUser;
  context: AnalyticsContext;
  props: AnalyticsEventProps;
};

let queue: AnalyticsEventPayload[] = [];
let flushTimer: number | null = null;
let isFlushing = false;
let identityPromise: Promise<AnalyticsUser> | null = null;
let listenersBound = false;
let sessionSnapshot = getSupabaseSessionSnapshot();

if (typeof window !== 'undefined') {
  subscribeToSupabaseSession((state) => {
    sessionSnapshot = state;
    if (state.status !== 'loading') {
      identityPromise = null;
    }
  });
}

function isBrowser(): boolean {
  return typeof window !== 'undefined';
}

function scheduleFlush(): void {
  if (!isBrowser()) return;
  if (flushTimer !== null || queue.length === 0) return;
  flushTimer = window.setTimeout(() => {
    flushTimer = null;
    void flushQueue('timer');
  }, FLUSH_INTERVAL_MS);
}

function clearFlushTimer(): void {
  if (flushTimer !== null) {
    clearTimeout(flushTimer);
    flushTimer = null;
  }
}

function getRoute(): string {
  if (!isBrowser()) return 'server';
  try {
    return stripUrlQueryAndHash(window.location?.pathname ?? 'unknown');
  } catch (error) {
    if (DEBUG_ENABLED) {
      console.warn('[analytics] failed to read route', error);
    }
    return 'unknown';
  }
}

function getAnonId(): string {
  if (!isBrowser()) {
    return 'server-anon';
  }

  try {
    const stored = window.localStorage.getItem(STORAGE_KEY);
    if (stored) {
      return stored;
    }
    const generated =
      window.crypto?.randomUUID?.() ?? `anon-${Math.random().toString(36).slice(2, 12)}`;
    window.localStorage.setItem(STORAGE_KEY, generated);
    return generated;
  } catch (error) {
    if (DEBUG_ENABLED) {
      console.warn('[analytics] unable to access localStorage for anonId', error);
    }
    return window.crypto?.randomUUID?.() ?? `anon-${Math.random().toString(36).slice(2, 12)}`;
  }
}

async function hashEmail(email: string | null | undefined): Promise<string | null> {
  const normalized = email?.trim().toLowerCase();
  if (!normalized) return null;

  try {
    if (typeof window !== 'undefined' && !window.crypto?.subtle) {
      return null;
    }

    const encoder = new TextEncoder();
    const data = encoder.encode(normalized);
    const digest = await crypto.subtle.digest('SHA-256', data);
    const bytes = new Uint8Array(digest);
    return Array.from(bytes)
      .map((byte) => byte.toString(16).padStart(2, '0'))
      .join('');
  } catch (error) {
    if (DEBUG_ENABLED) {
      console.warn('[analytics] failed to hash email', error);
    }
    return null;
  }
}

async function resolveIdentity(): Promise<AnalyticsUser> {
  if (identityPromise) {
    return identityPromise;
  }

  identityPromise = (async () => {
    const anonId = getAnonId();
    const snapshot = sessionSnapshot;
    if (snapshot.status === 'authenticated' || snapshot.status === 'unauthenticated') {
      const emailHash = await hashEmail(snapshot.user?.email ?? null);
      return { anonId, emailHash };
    }
    try {
      const supabase = getSupabaseBrowserClient();
      const { data } = await supabase.auth.getUser();
      const email = data?.user?.email ?? null;
      const emailHash = await hashEmail(email);
      return { anonId, emailHash };
    } catch (error) {
      if (DEBUG_ENABLED) {
        console.warn('[analytics] failed to resolve identity', error);
      }
      return { anonId, emailHash: null };
    }
  })().catch((error) => {
    if (DEBUG_ENABLED) {
      console.warn('[analytics] identity promise rejected', error);
    }
    identityPromise = null;
    return { anonId: getAnonId(), emailHash: null as string | null };
  });

  return identityPromise;
}

async function buildEvent(
  name: string,
  payload?: Record<string, unknown>,
): Promise<AnalyticsEventPayload> {
  const user = await resolveIdentity();
  const context: AnalyticsContext = {
    route: getRoute(),
    version: APP_VERSION,
  };

  return {
    name,
    ts: new Date().toISOString(),
    user,
    context,
    props: sanitizeAnalyticsProps(payload) ?? {},
  };
}

async function dispatch(events: AnalyticsEventPayload[]): Promise<void> {
  if (!isBrowser() || events.length === 0) return;

  const body = JSON.stringify({ events });

  try {
    if (typeof navigator !== 'undefined' && typeof navigator.sendBeacon === 'function') {
      const blob = new Blob([body], { type: 'application/json' });
      const dispatched = navigator.sendBeacon(EVENT_ENDPOINT, blob);
      if (dispatched) {
        return;
      }
    }
  } catch (error) {
    if (DEBUG_ENABLED) {
      console.warn('[analytics] sendBeacon failed, falling back to fetch', error);
    }
  }

  await fetch(EVENT_ENDPOINT, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body,
    keepalive: true,
  });
}

async function flushQueue(trigger: 'timer' | 'visibility' | 'manual'): Promise<void> {
  if (isFlushing || queue.length === 0) {
    return;
  }

  isFlushing = true;
  clearFlushTimer();

  const batch = queue;
  queue = [];

  if (DEBUG_ENABLED) {
    console.debug('[analytics] flushing events', trigger, batch);
  }

  try {
    await dispatch(batch);
  } catch (error) {
    if (DEBUG_ENABLED) {
      console.warn('[analytics] failed to flush events', error);
    }
    queue = batch.concat(queue);
    scheduleFlush();
  } finally {
    isFlushing = false;
  }
}

function bindLifecycleListeners(): void {
  if (!isBrowser() || listenersBound) return;

  const handler = () => {
    void flushQueue('visibility');
  };

  window.addEventListener('visibilitychange', handler, { passive: true });
  window.addEventListener('pagehide', handler, { passive: true });
  window.addEventListener('beforeunload', handler, { passive: true });
  listenersBound = true;
}

export async function emit(eventName: string, payload?: Record<string, unknown>): Promise<void> {
  if (!isBrowser()) return;

  bindLifecycleListeners();

  try {
    const event = await buildEvent(eventName, payload);

    if (DEBUG_ENABLED) {
      console.debug('[analytics]', eventName, event.props);
    }

    queue.push(event);

    if (queue.length >= MAX_BATCH_SIZE) {
      clearFlushTimer();
      void flushQueue('manual');
    } else {
      scheduleFlush();
    }
  } catch (error) {
    if (DEBUG_ENABLED) {
      console.warn('[analytics] emit failed', eventName, error);
    }
  }
}

if (isBrowser()) {
  // Warm up identity resolution eagerly so the first emit has cached context.
  void resolveIdentity();
}

export async function flushPendingEvents(): Promise<void> {
  await flushQueue('manual');
}

import { stripUrlQueryAndHash } from '@/lib/security/url-redaction';

type JsonPrimitive = string | number | boolean | null;
export type AnalyticsJsonValue =
  | JsonPrimitive
  | AnalyticsJsonValue[]
  | { [key: string]: AnalyticsJsonValue };

export type AnalyticsProps = Record<string, AnalyticsJsonValue>;

const ALLOWED_ANALYTICS_PROP_KEYS = new Set([
  'bookingId',
  'booking_id',
  'code',
  'date',
  'fields',
  'hasAvatar',
  'idempotent',
  'is_online',
  'kind',
  'method',
  'party',
  'path',
  'range',
  'redirectedFrom',
  'referrer',
  'reservationId',
  'restaurantId',
  'restaurant_id',
  'section',
  'size',
  'source',
  'status',
  'surface',
  'type',
  'view',
]);

const QUERY_STRIPPED_PROP_KEYS = new Set(['path', 'redirectedFrom', 'route', 'referrer']);

function toAnalyticsJsonValue(value: unknown): AnalyticsJsonValue | undefined {
  if (
    value === null ||
    typeof value === 'string' ||
    typeof value === 'number' ||
    typeof value === 'boolean'
  ) {
    return value;
  }
  if (Array.isArray(value)) {
    const arrayValue = value
      .map((entry) => toAnalyticsJsonValue(entry))
      .filter((entry): entry is AnalyticsJsonValue => entry !== undefined);
    return arrayValue;
  }
  return undefined;
}

export function sanitizeAnalyticsProps(
  input?: Record<string, unknown>,
): AnalyticsProps | undefined {
  if (!input) return undefined;

  const props: AnalyticsProps = {};
  for (const [key, rawValue] of Object.entries(input)) {
    if (!ALLOWED_ANALYTICS_PROP_KEYS.has(key)) continue;
    const value = toAnalyticsJsonValue(rawValue);
    if (value === undefined || value === null) continue;
    props[key] =
      typeof value === 'string' && QUERY_STRIPPED_PROP_KEYS.has(key)
        ? stripUrlQueryAndHash(value)
        : value;
  }

  return Object.keys(props).length > 0 ? props : undefined;
}

export interface HttpErrorInit {
  message: string;
  status: number;
  code?: string;
  details?: unknown;
  cause?: unknown;
}

export class HttpError extends Error {
  readonly status: number;
  readonly code: string;
  readonly details?: unknown;

  constructor({ message, status, code, details, cause }: HttpErrorInit) {
    super(message, { cause });
    this.name = 'HttpError';
    this.status = status;
    this.code = code ?? `HTTP_${status}`;
    this.details = details;
  }
}

export type ErrorLikeBody = {
  message?: unknown;
  status?: unknown;
  code?: unknown;
  details?: unknown;
};

export function normalizeError({
  status,
  statusText,
  body,
  cause,
}: {
  status: number;
  statusText?: string;
  body?: ErrorLikeBody | null;
  cause?: unknown;
}): HttpError {
  const parsedMessage =
    typeof body?.message === 'string' && body.message.trim().length > 0
      ? body.message.trim()
      : statusText && statusText.trim().length > 0
        ? statusText
        : `Request failed with status ${status}`;

  const parsedCode =
    typeof body?.code === 'string' && body.code.trim().length > 0
      ? body.code.trim()
      : `HTTP_${status}`;

  return new HttpError({
    message: parsedMessage,
    status,
    code: parsedCode,
    details: body?.details,
    cause,
  });
}

import { CSRF_HEADER_NAME, getBrowserCsrfToken } from '@/lib/security/csrf';

import { HttpError, normalizeError } from './errors';

export type FetchJsonInit = RequestInit & {
  parseJson?: (text: string) => unknown;
};

const defaultParseJson = (text: string) => JSON.parse(text) as unknown;

function ensureHeaders(initHeaders?: HeadersInit): Headers {
  const headers = new Headers(initHeaders);
  if (!headers.has('Accept')) {
    headers.set('Accept', 'application/json');
  }
  return headers;
}

export async function fetchJson<T>(input: RequestInfo | URL, init: FetchJsonInit = {}): Promise<T> {
  const { parseJson = defaultParseJson, ...rest } = init;
  const headers = ensureHeaders(rest.headers);
  const csrfToken = getBrowserCsrfToken();
  if (csrfToken && !headers.has(CSRF_HEADER_NAME)) {
    headers.set(CSRF_HEADER_NAME, csrfToken);
  }

  const response = await fetch(input, {
    ...rest,
    headers,
    credentials: rest.credentials ?? 'include',
  });

  const shouldTriggerAuthRedirect = response.status === 401 || response.status === 419;
  if (shouldTriggerAuthRedirect && typeof window !== 'undefined') {
    void import('@/lib/http/sessionRedirect').then((mod) => mod.triggerSessionRedirect()).catch(() => {});
  }

  let text: string | null = null;
  try {
    text = await response.text();
  } catch (cause) {
    if (!response.ok) {
      throw normalizeError({
        status: response.status,
        statusText: response.statusText,
        cause,
      });
    }
    throw new HttpError({
      message: 'Failed to read response body',
      status: response.status,
      code: 'READ_ERROR',
      cause,
    });
  }

  let parsed: unknown = undefined;
  let parseError: unknown = undefined;
  if (text && text.length > 0) {
    try {
      parsed = parseJson(text);
    } catch (cause) {
      parseError = cause;
    }
  }

  if (!response.ok) {
    const errorBody = typeof parsed === 'object' && parsed !== null ? (parsed as Record<string, unknown>) : undefined;
    throw normalizeError({
      status: response.status,
      statusText: response.statusText,
      body: errorBody,
      cause: parseError,
    });
  }

  if (parseError) {
    throw new HttpError({
      message: 'Failed to parse JSON response',
      status: response.status,
      code: 'INVALID_JSON',
      cause: parseError,
    });
  }

  return (parsed as T) ?? (undefined as T);
}

'use client';

export const SESSION_EXPIRED_EVENT = 'session:expired';

let redirectInFlight = false;
let lastPath: string | null = null;
let lastSignalTs = 0;
const SIGNAL_DEBOUNCE_MS = 1500;

export function triggerSessionRedirect(path?: string, message?: string) {
  if (typeof window === 'undefined') return;

  const currentPath = path ?? `${window.location.pathname}${window.location.search}`;
  if (!currentPath || currentPath.startsWith('/auth')) return;

  if (redirectInFlight && lastPath === currentPath) return;

  const now = Date.now();
  if (now - lastSignalTs > SIGNAL_DEBOUNCE_MS) {
    window.dispatchEvent(
      new CustomEvent(SESSION_EXPIRED_EVENT, {
        detail: {
          message: message ?? 'Please sign in again to continue.',
          path: currentPath,
        },
      }),
    );
    lastSignalTs = now;
  }

  const target = `/auth/signin?redirectedFrom=${encodeURIComponent(currentPath)}`;
  redirectInFlight = true;
  lastPath = currentPath;
  window.location.assign(target);
}

import { resolveCookieDomain } from '@/lib/supabase/cookies';

export const OPS_ACTIVE_RESTAURANT_STORAGE_KEY = 'ops.activeRestaurantId';
export const OPS_ACTIVE_RESTAURANT_COOKIE_NAME = 'ops-active-restaurant';

const OPS_ACTIVE_RESTAURANT_MAX_AGE_SECONDS = 60 * 60 * 24 * 30;

function deriveRootDomain(hostname: string): string | undefined {
  if (!hostname || hostname === 'localhost' || hostname.startsWith('127.')) {
    return undefined;
  }

  const parts = hostname.split('.');
  if (parts.length < 2) {
    return undefined;
  }

  return parts.slice(-2).join('.');
}

function resolveBrowserRootDomain(): string | undefined {
  if (typeof window === 'undefined') {
    return undefined;
  }

  const configuredRootDomain = process.env.NEXT_PUBLIC_ROOT_DOMAIN?.trim();
  if (configuredRootDomain && configuredRootDomain !== 'localhost') {
    return configuredRootDomain;
  }

  return deriveRootDomain(window.location.hostname);
}

export function resolvePreferredOpsRestaurantId(
  restaurantIds: readonly string[],
  preferredRestaurantId?: string | null,
): string | null {
  if (preferredRestaurantId && restaurantIds.includes(preferredRestaurantId)) {
    return preferredRestaurantId;
  }

  return restaurantIds[0] ?? null;
}

export function writeBrowserOpsRestaurantCookie(restaurantId: string | null): void {
  if (typeof document === 'undefined') {
    return;
  }

  const secure = typeof window !== 'undefined' ? window.location.protocol === 'https:' : false;
  const rootDomain = resolveBrowserRootDomain();
  const resolvedDomain = resolveCookieDomain(rootDomain);
  const maxAge = restaurantId ? OPS_ACTIVE_RESTAURANT_MAX_AGE_SECONDS : 0;
  const encodedValue = restaurantId ? encodeURIComponent(restaurantId) : '';
  const attributes = [
    `max-age=${maxAge}`,
    'path=/',
    'samesite=lax',
    resolvedDomain ? `domain=${resolvedDomain}` : null,
    secure ? 'secure' : null,
  ]
    .filter(Boolean)
    .join('; ');

  document.cookie = `${OPS_ACTIVE_RESTAURANT_COOKIE_NAME}=${encodedValue}; ${attributes}`;
}

