  templates: Partial<Record<RestaurantBookingEmailTemplateKey, RestaurantEmailTemplateOverride>>;
};

export type BookingEmailTemplateVariableMap = {
  name: string;
  firstName: string;
  venue: string;
  date: string;
  time: string;
  party: string;
};

export const BOOKING_EMAIL_TEMPLATE_VARIABLE_KEYS = [
