import { resolveCookieDomain } from "@/lib/supabase/cookies";

const TOKEN_COOKIE_NAME = "sr-csrf-token";
const TOKEN_HEADER_NAME = "x-csrf-token";
const TOKEN_COOKIE_MAX_AGE_SECONDS = 60 * 60 * 24 * 3; // 3 days
const TOKEN_BYTES = 32;

type CsrfCookieOptions = {
  domain?: string;
  maxAge: number;
  sameSite: "lax";
  path: "/";
  secure: boolean;
  httpOnly: false;
};

type CsrfCookieConfig = {
  rootDomain?: string | null;
  secure: boolean;
};

function readCookieValue(source: string, name: string): string | null {
  if (!source || !name) {
    return null;
  }

  const escaped = name.replace(/[-/\\^$*+?.()|[\]{}]/g, "\\$&");
  const pattern = new RegExp(`(?:^|;\\s*)${escaped}\\s*=\\s*([^;]+)`);
  const match = source.match(pattern);
  return match?.[1] ? decodeURIComponent(match[1]) : null;
}

function generateToken(): string | null {
  if (typeof crypto === "undefined" || typeof crypto.getRandomValues !== "function") return null;
  const bytes = new Uint8Array(TOKEN_BYTES);
  crypto.getRandomValues(bytes);
  return Array.from(bytes)
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("");
}

function deriveRootDomain(hostname: string): string | undefined {
  if (!hostname || hostname === "localhost" || hostname.startsWith("127.")) return undefined;
  const parts = hostname.split(".");
  if (parts.length < 2) return undefined;
  return parts.slice(-2).join(".");
}

function resolveBrowserRootDomain(): string | undefined {
  if (typeof window === "undefined") return undefined;
  const envRoot = process.env.NEXT_PUBLIC_ROOT_DOMAIN?.trim();
  if (envRoot && envRoot !== "localhost") return envRoot;
  return deriveRootDomain(window.location.hostname);
}

export function buildCsrfCookieOptions({ rootDomain, secure }: CsrfCookieConfig): CsrfCookieOptions {
  const resolvedDomain = resolveCookieDomain(rootDomain ?? undefined);
  const options: CsrfCookieOptions = {
    maxAge: TOKEN_COOKIE_MAX_AGE_SECONDS,
    sameSite: "lax",
    path: "/",
    secure,
    httpOnly: false,
  };
  if (resolvedDomain) {
    options.domain = resolvedDomain;
  }
  return options;
}

function setBrowserCsrfCookie(token: string) {
  if (typeof document === "undefined") return;
  const secure = typeof location !== "undefined" ? location.protocol === "https:" : false;
  const rootDomain = resolveBrowserRootDomain();
  const options = buildCsrfCookieOptions({ rootDomain, secure });
  const attributes = [
    `max-age=${options.maxAge}`,
    `path=${options.path}`,
    `samesite=${options.sameSite}`,
    options.domain ? `domain=${options.domain}` : null,
    options.secure ? "secure" : null,
  ]
    .filter(Boolean)
    .join("; ");
  document.cookie = `${TOKEN_COOKIE_NAME}=${encodeURIComponent(token)}; ${attributes}`;
}

export function getBrowserCsrfToken(): string | null {
  if (typeof document === "undefined" || typeof document.cookie !== "string") {
    return null;
  }
  const existing = readCookieValue(document.cookie, TOKEN_COOKIE_NAME);
  if (existing) {
    setBrowserCsrfCookie(existing);
    return existing;
  }

  const token = generateToken();
  if (token) {
    setBrowserCsrfCookie(token);
    return token;
  }
  return null;
}

export function getCsrfConstants() {
  return {
    cookieName: TOKEN_COOKIE_NAME,
    headerName: TOKEN_HEADER_NAME,
    cookieMaxAgeSeconds: TOKEN_COOKIE_MAX_AGE_SECONDS,
  } as const;
}

export const CSRF_COOKIE_NAME = TOKEN_COOKIE_NAME;
export const CSRF_HEADER_NAME = TOKEN_HEADER_NAME;
export const CSRF_COOKIE_MAX_AGE_SECONDS = TOKEN_COOKIE_MAX_AGE_SECONDS;

const FORBIDDEN_SCHEMES = new Set(['javascript:', 'data:', 'vbscript:', 'file:', 'blob:']);

const GOOGLE_MAPS_HOSTS = new Set(['g.page', 'maps.app.goo.gl']);
const GOOGLE_HOST_SUFFIXES = [
  'google.com',
  'google.co.uk',
  'google.co.in',
  'google.ca',
  'google.com.au',
  'google.ie',
  'google.fr',
  'google.de',
  'google.es',
  'google.it',
  'google.nl',
];

function isGoogleHost(hostname: string): boolean {
  const host = hostname.toLowerCase();
  return GOOGLE_HOST_SUFFIXES.some((suffix) => host === suffix || host.endsWith(`.${suffix}`));
}

function isGoogleMapsHost(hostname: string): boolean {
  const host = hostname.toLowerCase();
  return GOOGLE_MAPS_HOSTS.has(host) || isGoogleHost(host);
}

function hasAllowedProtocol(url: URL, protocols: ReadonlySet<string>): boolean {
  const protocol = url.protocol.toLowerCase();
  return protocols.has(protocol) && !FORBIDDEN_SCHEMES.has(protocol);
}

function parseAbsoluteUrl(value: string | null | undefined): URL | null {
  if (typeof value !== 'string') {
    return null;
  }

  const trimmed = value.trim();
  if (!trimmed) {
    return null;
  }

  try {
    return new URL(trimmed);
  } catch {
    return null;
  }
}

function normalizeUrl(url: URL): string {
  url.protocol = url.protocol.toLowerCase();
  url.hostname = url.hostname.toLowerCase();
  return url.toString();
}

export function safeHttpUrl(value: string | null | undefined): string | null {
  const url = parseAbsoluteUrl(value);
  if (!url || !hasAllowedProtocol(url, new Set(['http:', 'https:']))) {
    return null;
  }

  return normalizeUrl(url);
}

export function safeHttpsUrl(value: string | null | undefined): string | null {
  const url = parseAbsoluteUrl(value);
  if (!url || !hasAllowedProtocol(url, new Set(['https:']))) {
    return null;
  }

  return normalizeUrl(url);
}

export function safeGoogleMapsUrl(value: string | null | undefined): string | null {
  const url = parseAbsoluteUrl(value);
  if (!url || !hasAllowedProtocol(url, new Set(['https:'])) || !isGoogleMapsHost(url.hostname)) {
    return null;
  }

  return normalizeUrl(url);
}

export function safeGoogleReviewUrl(value: string | null | undefined): string | null {
  const url = parseAbsoluteUrl(value);
  if (!url || !hasAllowedProtocol(url, new Set(['https:'])) || !isGoogleMapsHost(url.hostname)) {
    return null;
  }

  const pathname = url.pathname.toLowerCase();
  const href = url.toString().toLowerCase();
  const isReviewPath =
    url.hostname.toLowerCase() === 'g.page' ||
    pathname.includes('review') ||
    pathname.includes('writereview') ||
    href.includes('/local/reviews') ||
    href.includes('writereview') ||
    href.includes('review');

  return isReviewPath ? normalizeUrl(url) : null;
}

function isSafeRelativeHref(value: string): boolean {
  return value.startsWith('/') && !value.startsWith('//') && !value.includes('\\');
}

export function safePublicHref(value: string | null | undefined, fallback: string): string {
  const trimmed = typeof value === 'string' ? value.trim() : '';
  if (trimmed && isSafeRelativeHref(trimmed)) {
    return trimmed;
  }

  const safeAbsolute = safeHttpUrl(trimmed);
  if (safeAbsolute) {
    return safeAbsolute;
  }

  const fallbackTrimmed = fallback.trim();
  if (isSafeRelativeHref(fallbackTrimmed)) {
    return fallbackTrimmed;
  }

  return safeHttpUrl(fallbackTrimmed) ?? '/';
}

const REDACTED_QUERY_VALUE = '[redacted]';

export function stripUrlQueryAndHash(value: string): string {
  try {
    const url = new URL(value, 'https://nabatable.local');
    const path = `${url.pathname}${url.hash ? '' : ''}`;
    if (value.startsWith('http://') || value.startsWith('https://')) {
      return `${url.origin}${path}`;
    }
    return path || '/';
  } catch {
    const [withoutHash] = value.split('#', 1);
    const [withoutQuery] = withoutHash.split('?', 1);
    return withoutQuery || value;
  }
}

export function redactUrlQuery(value: string): string {
  const looksUrlLike =
    value.includes('?') &&
    (value.startsWith('/') || value.startsWith('http://') || value.startsWith('https://'));
  if (!looksUrlLike) return value;

  try {
    const isAbsolute = value.startsWith('http://') || value.startsWith('https://');
    const url = new URL(value, 'https://nabatable.local');
    for (const key of Array.from(url.searchParams.keys())) {
      url.searchParams.set(key, REDACTED_QUERY_VALUE);
    }
    const redacted = `${url.pathname}${url.search}${url.hash}`;
    return isAbsolute ? `${url.origin}${redacted}` : redacted;
  } catch {
    return value.replace(/([?&][^=&\s]+)=([^&\s]*)/g, `$1=${REDACTED_QUERY_VALUE}`);
  }
}

const PLACEHOLDER_ORIGIN = 'https://ops.local';

const ABSOLUTE_URL_PATTERN = /^[a-zA-Z][a-zA-Z\d+\-.]*:\/\//;

function ensureLeadingSlash(pathname: string): string {
  if (!pathname || pathname === '/') {
    return '/';
  }
  return pathname.startsWith('/') ? pathname : `/${pathname}`;
}

export function normalizeOpsPathname(target: string): string {
  const url = new URL(target, PLACEHOLDER_ORIGIN);
  const pathname = ensureLeadingSlash(url.pathname);

  if (pathname === '/app') {
    return '/';
  }

  if (pathname.startsWith('/app/')) {
    return pathname.slice(4);
  }

  return pathname;
}

export function opsHref(target: string): string {
  const isAbsolute = ABSOLUTE_URL_PATTERN.test(target);
  const url = new URL(target, isAbsolute ? undefined : PLACEHOLDER_ORIGIN);
  const normalizedPathname = ensureLeadingSlash(url.pathname);

  url.pathname =
    normalizedPathname === '/app' || normalizedPathname.startsWith('/app/')
      ? normalizedPathname
      : normalizedPathname === '/'
        ? '/app'
        : `/app${normalizedPathname}`;

  if (isAbsolute) {
    return url.toString();
  }

  return `${url.pathname}${url.search}${url.hash}`;
}

const PLACEHOLDER_ORIGIN = 'https://sajiloreservex.local';

const ABSOLUTE_URL_PATTERN = /^[a-zA-Z][a-zA-Z\d+\-.]*:\/\//;

type ExtraParams = Record<string, string | null | undefined>;

/**
 * Returns a path (relative or absolute) that appends/updates the `redirectedFrom` query parameter.
 * Existing query parameters on the base path are preserved, and new extras can be supplied.
 */
export function withRedirectedFrom(basePath: string, redirectedFrom: string, extras?: ExtraParams): string {
  const isAbsolute = ABSOLUTE_URL_PATTERN.test(basePath);
  const url = new URL(basePath, isAbsolute ? undefined : PLACEHOLDER_ORIGIN);

  if (extras) {
    for (const [key, value] of Object.entries(extras)) {
      if (typeof value === 'string' && value.length > 0) {
        url.searchParams.set(key, value);
      }
    }
  }

  url.searchParams.set('redirectedFrom', redirectedFrom);

  if (isAbsolute) {
    return url.toString();
  }

  return `${url.pathname}${url.search}${url.hash}`;
}

