export type OccasionKey = string;
const DATE_REGEX = /^\d{4}-\d{2}-\d{2}$/;

export const occasionAvailabilityRuleSchema = z.discriminatedUnion('kind', [
  z.object({
    kind: z.literal('anytime') as z.ZodLiteral<'anytime'>,
  }),
  z.object({
    kind: z.literal('time_window') as z.ZodLiteral<'time_window'>,
    start: z.string().min(1),
    end: z.string().min(1),
  }),
  z.object({
    kind: z.literal('month_only') as z.ZodLiteral<'month_only'>,
    months: z.array(z.number().int().min(1).max(12)).min(1),
  }),
  z.object({
    kind: z.literal('date_range') as z.ZodLiteral<'date_range'>,
    start: z.string().regex(DATE_REGEX),
    end: z.string().regex(DATE_REGEX),
  }),
  z.object({
    kind: z.literal('specific_dates') as z.ZodLiteral<'specific_dates'>,
    dates: z.array(z.string().regex(DATE_REGEX)).min(1),
  }),
]);

export type OccasionAvailabilityRule = z.infer<typeof occasionAvailabilityRuleSchema>;

export type OccasionDefinition = {
  key: OccasionKey;
  label: string;
  shortLabel: string;
  description: string | null;
  availability: OccasionAvailabilityRule[];
  defaultDurationMinutes: number;
  displayOrder: number;
  isActive: boolean;
};

export type RawOccasionRow = {
  key: string;
  label: string;
  short_label?: string | null;
  description?: string | null;
  availability?: unknown;
  default_duration_minutes?: number | null;
  display_order?: number | null;
  is_active?: boolean | null;
};

const ensureTime = (value: string): string | null => {
  const normalized = normalizeTime(value);
  if (!normalized) return null;
  return normalized;
};

const sanitizeRule = (rule: OccasionAvailabilityRule): OccasionAvailabilityRule | null => {
  switch (rule.kind) {
    case 'anytime':
      return rule;
    case 'time_window': {
      const start = ensureTime(rule.start);
      const end = ensureTime(rule.end);
      if (!start || !end) {
        return null;
      }
      if (toMinutes(end) <= toMinutes(start)) {
        return null;
      }
      return { kind: 'time_window', start, end };
    }
    case 'month_only': {
      const months = Array.from(
        new Set(rule.months.filter((month) => month >= 1 && month <= 12)),
      ).sort((a, b) => a - b);
      if (months.length === 0) {
        return null;
      }
      return { kind: 'month_only', months };
    }
    case 'date_range': {
      const { start, end } = rule;
      if (!DATE_REGEX.test(start) || !DATE_REGEX.test(end)) {
        return null;
      }
      if (start > end) {
        return { kind: 'date_range', start: end, end: start };
      }
      return rule;
    }
    case 'specific_dates': {
      const dates = Array.from(new Set(rule.dates.filter((date) => DATE_REGEX.test(date)))).sort();
      if (dates.length === 0) {
        return null;
      }
      return { kind: 'specific_dates', dates };
    }
    default:
      return null;
  }
};

const toAvailability = (value: unknown): OccasionAvailabilityRule[] => {
  if (!value) {
    return [];
  }
  try {
    const parsed = Array.isArray(value)
      ? value
      : typeof value === 'string'
        ? JSON.parse(value)
        : [];
    if (!Array.isArray(parsed)) {
      return [];
    }
    const result: OccasionAvailabilityRule[] = [];
    for (const entry of parsed) {
      const candidate = occasionAvailabilityRuleSchema.safeParse(entry);
      if (!candidate.success) {
        continue;
      }
      const sanitized = sanitizeRule(candidate.data);
      if (sanitized) {
        result.push(sanitized);
      }
    }
    return result;
  } catch (error) {
    if (process.env.NODE_ENV !== 'production') {
      console.warn('[occasions] failed to parse availability', { value, error });
    }
    return [];
  }
};

export function toOccasionDefinition(row: RawOccasionRow): OccasionDefinition {
  const trimmedKey = row.key?.trim();
  if (!trimmedKey) {
    throw new Error('Occasion key is required');
  }
  const trimmedLabel = row.label?.trim() ?? trimmedKey;
  const shortLabelRaw = row.short_label?.trim();
  const availability = toAvailability(row.availability);
  const defaultDurationMinutes =
    row.default_duration_minutes && Number.isFinite(row.default_duration_minutes)
      ? Math.max(1, Math.floor(row.default_duration_minutes))
      : 90;
  const displayOrder =
    row.display_order && Number.isFinite(row.display_order) ? Math.floor(row.display_order) : 0;
  const isActive = row.is_active ?? true;

  return {
    key: trimmedKey,
    label: trimmedLabel,
    shortLabel: shortLabelRaw && shortLabelRaw.length > 0 ? shortLabelRaw : trimmedLabel,
    description: row.description ?? null,
    availability,
    defaultDurationMinutes,
    displayOrder,
    isActive,
  } satisfies OccasionDefinition;
}

export function sortOccasions(definitions: OccasionDefinition[]): OccasionDefinition[] {
  return [...definitions].sort((a, b) => {
    if (a.displayOrder !== b.displayOrder) {
      return a.displayOrder - b.displayOrder;
    }
    return a.label.localeCompare(b.label);
  });
}

export type OccasionCatalog = {
  definitions: OccasionDefinition[];
  byKey: Map<OccasionKey, OccasionDefinition>;
  orderedKeys: OccasionKey[];
};

export function toOccasionCatalog(definitions: OccasionDefinition[]): OccasionCatalog {
  const active = definitions.filter((definition) => definition.isActive);
  const sorted = sortOccasions(active);
  const byKey = new Map<OccasionKey, OccasionDefinition>();
  const orderedKeys: OccasionKey[] = [];
  for (const definition of sorted) {
    byKey.set(definition.key, definition);
    orderedKeys.push(definition.key);
  }
  return { definitions: sorted, byKey, orderedKeys };
}

export function getFallbackOccasionCatalog(): OccasionCatalog {
  return toOccasionCatalog([]);
}

export type OccasionAvailabilityContext = {
  date: string;
  time?: string | null;
  timezone: string;
  month?: number;
};

const getMonthInTimezone = (date: string, timezone: string): number => {
  try {
    const reference = new Date(`${date}T12:00:00Z`);
    const formatter = new Intl.DateTimeFormat('en-US', { month: 'numeric', timeZone: timezone });
    const month = Number.parseInt(formatter.format(reference), 10);
    if (Number.isFinite(month)) {
      return month;
    }
  } catch (error) {
    if (process.env.NODE_ENV !== 'production') {
      console.warn('[occasions] failed to resolve month', { date, timezone, error });
    }
  }
  const fallback = new Date(`${date}T00:00:00Z`);
  return fallback.getUTCMonth() + 1;
};

const isWithinTimeWindow = (
  time: string | null | undefined,
  rule: Extract<OccasionAvailabilityRule, { kind: 'time_window' }>,
): boolean => {
  if (!time) {
    return true;
  }
  const normalized = normalizeTime(time);
  if (!normalized) {
    return false;
  }
  const target = toMinutes(normalized);
  return target >= toMinutes(rule.start) && target < toMinutes(rule.end);
};

export function isOccasionAvailable(
  definition: OccasionDefinition,
  context: OccasionAvailabilityContext,
): boolean {
  if (!definition.isActive) {
    return false;
  }
  if (definition.availability.length === 0) {
    return true;
  }
  return definition.availability.every((rule) => {
    switch (rule.kind) {
      case 'anytime':
        return true;
      case 'time_window':
        return isWithinTimeWindow(context.time ?? null, rule);
      case 'month_only': {
        const month = context.month ?? getMonthInTimezone(context.date, context.timezone);
        return rule.months.includes(month);
      }
      case 'date_range':
        return context.date >= rule.start && context.date <= rule.end;
      case 'specific_dates':
        return rule.dates.includes(context.date);
      default:
        return true;
    }
  });
}

export function coerceOccasionKey(
  options: OccasionCatalog,
  candidate: OccasionKey | null | undefined,
  fallback?: OccasionKey,
): OccasionKey {
  if (candidate && options.byKey.has(candidate)) {
    return candidate;
  }
  if (fallback && options.byKey.has(fallback)) {
    return fallback;
  }
  return options.orderedKeys[0] ?? fallback ?? 'dinner';
}

import { toMinutes } from './time';
import { isReservationDate } from './types';

import type { ReservationDate, ReservationTime } from './types';

export const LONDON_TIME_ZONE = 'Europe/London';

export function parseReservationDate(value: string | ReservationDate): ReservationDate {
  if (typeof value === 'string' && !isReservationDate(value)) {
    throw new Error(`Invalid reservation date: ${value}`);
  }
  return value as ReservationDate;
}

export function toDateMidnight(value: string | ReservationDate): Date {
  const date = parseReservationDate(value);
  return new Date(`${date}T00:00:00`);
}

export function createDateFromParts(
  date: string | ReservationDate,
  time: string | ReservationTime,
): Date {
  const normalizedDate = parseReservationDate(date);
  const minutes = toMinutes(time);
  const [hours, mins] = [Math.floor(minutes / 60), minutes % 60];
  const result = new Date(`${normalizedDate}T00:00:00`);
  result.setHours(hours, mins, 0, 0);
  return result;
}

export function isWeekend(date: Date): boolean {
  const day = date.getDay();
  return day === 0 || day === 6;
}

export function getDayKey(date: string | ReservationDate | Date): number {
  if (date instanceof Date) return date.getDay();
  return toDateMidnight(date).getDay();
}

export * from './types';
export * from './time';
export * from './date';
export * from './reservations';

import {
  reservationConfigResult,
  type ReservationConfig,
} from '@reserve/shared/config/reservations';
import { normalizeTime, slotsForRange, toMinutes } from '@reserve/shared/time';

import type { BookingOption } from '@reserve/shared/booking';
import type { ReservationTime } from '@reserve/shared/time';

export type ServiceWindow = {
  start: ReservationTime;
  end: ReservationTime;
};

export type ServiceWindows = {
  lunch: ServiceWindow;
  dinner: ServiceWindow;
};

function resolveConfig(config?: ReservationConfig): ReservationConfig {
  return config ?? reservationConfigResult.config;
}

function resolveBaseDate(dateInput: string | null | undefined): Date {
  if (dateInput) {
    const input = new Date(`${dateInput}T00:00:00`);
    if (!Number.isNaN(input.getTime())) {
      return input;
    }
  }
  const fallback = new Date();
  fallback.setHours(0, 0, 0, 0);
  return fallback;
}

export function getServiceWindows(
  date: string | null | undefined,
  config?: ReservationConfig,
): ServiceWindows {
  const resolvedConfig = resolveConfig(config);
  const baseDate = resolveBaseDate(date);
  const day = baseDate.getDay();
  const isWeekend = day === 0 || day === 6;
  const lunchEnd = isWeekend
    ? resolvedConfig.windows.weekendLunchEnd
    : resolvedConfig.windows.weekdayLunchEnd;

  return {
    lunch: { start: resolvedConfig.opening.open, end: lunchEnd },
    dinner: { start: resolvedConfig.windows.dinnerStart, end: resolvedConfig.opening.close },
  } satisfies ServiceWindows;
}

function minutesBetween(window: ServiceWindow): { start: number; end: number } {
  return {
    start: toMinutes(window.start),
    end: toMinutes(window.end),
  };
}

function isWithin(minutes: number, window: ServiceWindow | null | undefined): boolean {
  if (!window) return false;
  const range = minutesBetween(window);
  return minutes >= range.start && minutes < range.end;
}

export function getSlotsByService(
  date: string | null | undefined,
  config?: ReservationConfig,
): Record<BookingOption, ReservationTime[]> {
  const windows = getServiceWindows(date, config);
  const resolvedConfig = resolveConfig(config);
  return {
    lunch: slotsForRange(
      windows.lunch.start,
      windows.lunch.end,
      resolvedConfig.opening.intervalMinutes,
    ),
    dinner: slotsForRange(
      windows.dinner.start,
      windows.dinner.end,
      resolvedConfig.opening.intervalMinutes,
    ),
  } satisfies Record<BookingOption, ReservationTime[]>;
}

function toMinuteValue(value: string | ReservationTime | null | undefined): number {
  const normalized = normalizeTime(value);
  if (!normalized) return 0;
  return toMinutes(normalized);
}

export function inferBookingOption(
  time: string | ReservationTime | null | undefined,
  date: string | null | undefined,
  config?: ReservationConfig,
): BookingOption {
  const resolvedConfig = resolveConfig(config);
  const windows = getServiceWindows(date, resolvedConfig);
  const minutes = toMinuteValue(time);

  if (isWithin(minutes, windows.lunch)) {
    return 'lunch';
  }
  if (isWithin(minutes, windows.dinner)) {
    return 'dinner';
  }

  const dinnerStartMinutes = toMinutes(resolvedConfig.windows.dinnerStart);
  return minutes >= dinnerStartMinutes ? 'dinner' : 'lunch';
}

import { isReservationTime } from './types';

import type { ReservationTime } from './types';

export const MINUTES_PER_HOUR = 60;
export const MINUTES_PER_DAY = 24 * MINUTES_PER_HOUR;

export function normalizeTime(
  value: string | ReservationTime | null | undefined,
): ReservationTime | null {
  if (!value) return null;
  const raw = typeof value === 'string' ? value : (value as unknown as string);
  const trimmed = raw.trim();
  if (trimmed.length >= 5) {
    const candidate = trimmed.slice(0, 5);
    return isReservationTime(candidate) ? (candidate as ReservationTime) : null;
  }
  return isReservationTime(trimmed) ? (trimmed as ReservationTime) : null;
}

export function toMinutes(value: string | ReservationTime): number {
  const normalized = normalizeTime(value);
  if (!normalized) {
    throw new Error(`Invalid time value: ${value}`);
  }
  const [hours, minutes] = normalized.split(':').map(Number);
  return (hours || 0) * MINUTES_PER_HOUR + (minutes || 0);
}

export function fromMinutes(totalMinutes: number): ReservationTime {
  if (!Number.isFinite(totalMinutes)) {
    throw new Error(`Invalid minutes value: ${totalMinutes}`);
  }
  const clamped = ((totalMinutes % MINUTES_PER_DAY) + MINUTES_PER_DAY) % MINUTES_PER_DAY;
  const hours = Math.floor(clamped / MINUTES_PER_HOUR)
    .toString()
    .padStart(2, '0');
  const minutes = Math.floor(clamped % MINUTES_PER_HOUR)
    .toString()
    .padStart(2, '0');
  return `${hours}:${minutes}` as ReservationTime;
}

export function clampMinutes(value: number, min = 0, max = MINUTES_PER_DAY): number {
  if (min > max) {
    throw new Error(`Invalid clamp range: min ${min} greater than max ${max}`);
  }
  return Math.min(Math.max(value, min), max);
}

export function minutesBetween(
  start: string | ReservationTime,
  end: string | ReservationTime,
): number {
  return toMinutes(end) - toMinutes(start);
}

export function createMinutesRange(
  start: string | ReservationTime,
  end: string | ReservationTime,
  stepMinutes: number,
): number[] {
  if (stepMinutes <= 0) {
    throw new Error(`Step minutes must be positive. Received ${stepMinutes}`);
  }
  const startMinutes = toMinutes(start);
  const endMinutes = toMinutes(end);
  const result: number[] = [];
  for (let minutes = startMinutes; minutes < endMinutes; minutes += stepMinutes) {
    result.push(minutes);
  }
  return result;
}

export function slotsForRange(
  start: string | ReservationTime,
  end: string | ReservationTime,
  stepMinutes: number,
): ReservationTime[] {
  return createMinutesRange(start, end, stepMinutes).map((minutes) => fromMinutes(minutes));
}

export type Brand<T, Marker extends string> = T & { readonly __brand: Marker };

export type ReservationDate = Brand<string, 'ReservationDate'>;
export type ReservationTime = Brand<string, 'ReservationTime'>;

const DATE_REGEX = /^\d{4}-\d{2}-\d{2}$/;
const TIME_REGEX = /^([01]\d|2[0-3]):([0-5]\d)$/;

export function isReservationDate(value: string | null | undefined): value is ReservationDate {
  if (!value) return false;
  return DATE_REGEX.test(value);
}

export function isReservationTime(value: string | null | undefined): value is ReservationTime {
  if (!value) return false;
  return TIME_REGEX.test(value.trim());
}

export function toReservationDate(value: string): ReservationDate {
  if (!isReservationDate(value)) {
    throw new Error(`Invalid reservation date: ${value}`);
  }
  return value;
}

export function toReservationTime(value: string): ReservationTime {
  if (!isReservationTime(value)) {
    throw new Error(`Invalid reservation time: ${value}`);
  }
  return value.trim() as ReservationTime;
}

import { cookies } from 'next/headers';
import { redirect } from 'next/navigation';

import { RestaurantSettingsPageShell } from '@/components/features/restaurant-settings/RestaurantSettingsPageShell';
import {
  OPS_ACTIVE_RESTAURANT_COOKIE_NAME,
  resolvePreferredOpsRestaurantId,
} from '@/lib/ops/session';
import { withRedirectedFrom } from '@/lib/url/withRedirectedFrom';
import { getServerComponentSupabaseClient } from '@/server/supabase';
import { fetchUserMembershipsCached, requireAdminMembership } from '@/server/team/access';

import type { ReactNode } from 'react';

export default async function RestaurantSettingsLayout({ children }: { children: ReactNode }) {
  const supabase = await getServerComponentSupabaseClient();
  const {
    data: { user },
    error,
  } = await supabase.auth.getUser();

  if (error) {
    console.error('[settings/restaurant] failed to resolve auth', error.message);
  }

  if (!user) {
    redirect(withRedirectedFrom('/app/auth/signin', '/app/settings/restaurant/profile'));
  }

  const memberships = await fetchUserMembershipsCached(user.id);
  const cookieStore = await cookies();
  const activeRestaurantId = resolvePreferredOpsRestaurantId(
    memberships.map((membership) => membership.restaurant_id),
    cookieStore.get(OPS_ACTIVE_RESTAURANT_COOKIE_NAME)?.value ?? null,
  );

  if (!activeRestaurantId) {
    redirect('/app/bookings');
  }

  try {
    await requireAdminMembership({ userId: user.id, restaurantId: activeRestaurantId });
  } catch (membershipError) {
    console.warn('[settings/restaurant] denied non-admin settings access', {
      userId: user.id,
      restaurantId: activeRestaurantId,
      error: membershipError instanceof Error ? membershipError.message : String(membershipError),
    });
    redirect('/app/bookings');
  }

  return <RestaurantSettingsPageShell>{children}</RestaurantSettingsPageShell>;
}

